    provider_order_id text,
    pnr text,
    itinerary jsonb NOT NULL,
    traveler_snapshot jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    trip_id uuid,
    provider text DEFAULT '1A'::text,
    session_id text,
    search_key text,
    amadeus_key text,
    pricing_key text,
    is_ndc boolean DEFAULT false,
    ticket_numbers text[],
    fare_breakdown jsonb,
    policy_verdict text,
    policy_verdict_detail jsonb,
    result_index text,
    resolved_deal_codes jsonb,
    resolved_fop jsonb,
    sell_total numeric(12,2),
    commercials jsonb,
    share_token text,
    tmc_id uuid,
    booked_by uuid NOT NULL,
    confirmed_by uuid,
    policy_reason_code text,
    policy_reason_note text,
    purpose text DEFAULT 'business'::text NOT NULL,
    for_guest boolean DEFAULT false NOT NULL,
    CONSTRAINT bookings_policy_reason_code_check CHECK (((policy_reason_code IS NULL) OR (policy_reason_code = ANY (ARRAY['client_instruction'::text, 'no_compliant_option'::text, 'schedule_need'::text, 'lower_total_cost'::text, 'other'::text])))),
    CONSTRAINT bookings_policy_reason_note_check CHECK (((policy_reason_code IS DISTINCT FROM 'other'::text) OR (length(TRIM(BOTH FROM COALESCE(policy_reason_note, ''::text))) > 0))),
    CONSTRAINT bookings_policy_verdict_check CHECK (((policy_verdict IS NULL) OR (policy_verdict = ANY (ARRAY['green'::text, 'amber'::text, 'red'::text])))),
    CONSTRAINT bookings_purpose_check CHECK ((purpose = ANY (ARRAY['business'::text, 'personal'::text]))),
    CONSTRAINT bookings_status_check CHECK ((status = ANY (ARRAY['pending_approval'::text, 'approved'::text, 'approval_misconfigured'::text, 'rejected'::text, 'priced'::text, 'passenger_added'::text, 'held'::text, 'ticketed'::text, 'cancelled'::text, 'failed'::text])))
);


