);


--
-- Name: trips; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trips (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    created_by uuid NOT NULL,
    name text,
    description text,
    travel_date date,
    status text DEFAULT 'open'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tmc_id uuid,
    arranged_by uuid,
    travel_type text,
    billable boolean DEFAULT false NOT NULL,
    project text,
    currency text DEFAULT 'INR'::text NOT NULL,
    budget_amount numeric(12,2),
    cost_centre_id uuid,
    approval_status text DEFAULT 'none'::text NOT NULL,
    submitted_at timestamp with time zone,
    CONSTRAINT booking_groups_status_check CHECK ((status = ANY (ARRAY['open'::text, 'active'::text, 'completed'::text, 'cancelled'::text, 'deleted'::text]))),
    CONSTRAINT trips_approval_status_check CHECK ((approval_status = ANY (ARRAY['none'::text, 'pending'::text, 'approved'::text, 'rejected'::text, 'misconfigured'::text]))),
    CONSTRAINT trips_budget_amount_check CHECK (((budget_amount IS NULL) OR (budget_amount >= (0)::numeric))),
    CONSTRAINT trips_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT trips_travel_type_check CHECK (((travel_type IS NULL) OR (travel_type = ANY (ARRAY['domestic'::text, 'international'::text]))))
);


